async function checkNotifications(){if(notificationBusy||!("Notification"in window)||Notification.permission!=="granted")return;notificationBusy=true;try{const now=Date.now(),kmNow=maxRecordedKm();for(const item of itemsForReminders()){const source=item.source,kmLead=item.kind==="service"&&source.reminderKmEnabled===true?clampNumber(source.reminderKmLead,0):0,byDate=item.reminder.enabled&&item.date&&now>=triggerAt(item.date,item.reminder),byKm=item.km!==null&&((kmLead>0&&kmNow>=Math.max(0,item.km-kmLead))||(item.reminder.enabled&&kmNow>=item.km));if(!byDate&&!byKm)continue;const key=keyOf(item);if((source.notifiedKeys||[]).indexOf(key)>=0)continue;if(await sendNotification(item,key)){source.notifiedKeys=(source.notifiedKeys||[]).concat([key]).slice(-50);saveState();}}}finally{notificationBusy=false;}}
async function requestNotifications(){if(typeof window.requestDeviceNotifications==="function"){await window.requestDeviceNotifications();return;}if(!("Notification"in window)){updateNotificationStatus();return;}try{const result=await Notification.requestPermission();updateNotificationStatus();if(result==="granted"){showToast("اعلان‌های دستگاه برای یادآوری فعال شدند.");await checkNotifications();}}catch(error){showToast("گرفتن مجوز اعلان از مرورگر ممکن نشد.");}}
function askNotifications(){return requestNotifications();}
  function scrollToNearestDue(){setView("dashboard");const target=q("#documents-list .document-card.soon")||q("#documents-list .document-card.overdue")||q("#dashboard-due-section .due-card");if(!target)return;try{target.scrollIntoView({behavior:"smooth",block:"center"});}catch(error){target.scrollIntoView();}}
  function refreshDateViews(){const current=todayIso();if(current!==lastRenderedDate){lastRenderedDate=current;render();}}
  function openAutoBackupDb(){if(!window.indexedDB)return Promise.reject(new Error("IndexedDB ناموجود است"));if(autoBackupDbPromise)return autoBackupDbPromise;autoBackupDbPromise=new Promise(function(resolve,reject){const request=indexedDB.open(AUTO_BACKUP_DB,1);request.onupgradeneeded=function(){if(!request.result.objectStoreNames.contains(AUTO_BACKUP_STORE))request.result.createObjectStore(AUTO_BACKUP_STORE,{keyPath:"month"});};request.onsuccess=function(){const db=request.result;db.onversionchange=function(){db.close();autoBackupDbPromise=null;};resolve(db);};request.onerror=function(){autoBackupDbPromise=null;reject(request.error||new Error("فضای پشتیبان خودکار باز نشد"));};request.onblocked=function(){autoBackupDbPromise=null;reject(new Error("فضای پشتیبان خودکار مشغول است"));};});return autoBackupDbPromise;}
  function listAutoBackups(){return openAutoBackupDb().then(function(db){return new Promise(function(resolve,reject){const req=db.transaction(AUTO_BACKUP_STORE,"readonly").objectStore(AUTO_BACKUP_STORE).openCursor(),items=[];req.onsuccess=function(){const cursor=req.result;if(cursor){items.push(cursor.value);cursor.continue();}else resolve(items);};req.onerror=function(){reject(req.error||new Error("خواندن پشتیبان خودکار ممکن نشد"));};});});}
  function saveAutoBackup(item){return openAutoBackupDb().then(function(db){return new Promise(function(resolve,reject){const tx=db.transaction(AUTO_BACKUP_STORE,"readwrite");tx.objectStore(AUTO_BACKUP_STORE).put(item);tx.oncomplete=function(){resolve(true);};tx.onerror=function(){reject(tx.error||new Error("ذخیرهٔ پشتیبان خودکار ناموفق بود"));};tx.onabort=function(){reject(tx.error||new Error("ذخیرهٔ پشتیبان خودکار لغو شد"));};});});}
  function deleteAutoBackup(month){return openAutoBackupDb().then(function(db){return new Promise(function(resolve,reject){const tx=db.transaction(AUTO_BACKUP_STORE,"readwrite");tx.objectStore(AUTO_BACKUP_STORE).delete(month);tx.oncomplete=function(){resolve(true);};tx.onerror=function(){reject(tx.error||new Error("حذف پشتیبان قدیمی ممکن نشد"));};});});}
  function hasUserData(){const v=state&&state.vehicle||{};return !!((state&&state.entries&&state.entries.length)||(state&&state.documents&&state.documents.length)||v.model||v.year||v.plate||Number(v.odometer)>0||(v.label&&v.label!=="خودروی من"));}
  function currentBackupMonth(){const p=jalaliParts(todayIso());return p?String(p.year)+"/"+String(p.month).padStart(2,"0"):null;}
  async function maybeCreateMonthlyBackup(){if(autoBackupInFlight||!hasUserData())return;const month=currentBackupMonth();if(!month)return;autoBackupInFlight=true;try{const existing=(await listAutoBackups()).some(function(item){return item.month===month;});if(existing)return;const refs=new Set(state.entries.concat(state.documents).map(function(item){return item.photoId;}).filter(Boolean)),photos=refs.size?(await idbGetAll()).filter(function(photo){return refs.has(photo.id);}):[],snapshot={month:month,createdAt:new Date().toISOString(),state:JSON.parse(JSON.stringify(state)),photos:photos};if(JSON.stringify(snapshot).length>25*1024*1024){const status=q("#auto-backup-status");if(status)status.textContent="پشتیبان این ماه به‌دلیل حجم زیاد ساخته نشد؛ نسخهٔ دانلودی بگیرید.";return;}await saveAutoBackup(snapshot);const saved=(await listAutoBackups()).sort(function(a,b){return b.month.localeCompare(a.month);});for(const old of saved.slice(2))await deleteAutoBackup(old.month);}catch(error){const status=q("#auto-backup-status");if(status)status.textContent="پشتیبان خودکار ساخته نشد؛ نسخهٔ دانلودی را بگیرید.";}finally{autoBackupInFlight=false;}}
  async function restoreAutoBackupIfEmpty(){if(hasUserData())return;try{const backups=(await listAutoBackups()).sort(function(a,b){return b.month.localeCompare(a.month);}),latest=backups[0];if(!latest||hasUserData())return;if(!window.confirm("اطلاعاتی پیدا نشد. آخرین پشتیبان ماهانه بازیابی شود؟"))return;const previousState=state,previousPhotos=await idbGetAll();try{await idbReplaceAll(Array.isArray(latest.photos)?latest.photos:[]);state=normState(latest.state);state.version=DATA_VERSION;if(!saveState()){state=previousState;await idbReplaceAll(previousPhotos);return;}render();showToast("پشتیبان ماهانه بازیابی شد.");}catch(error){state=previousState;try{await idbReplaceAll(previousPhotos);}catch(ignored){}showToast("بازیابی پشتیبان ماهانه ممکن نشد.");}}catch(error){const status=q("#auto-backup-status");if(status)status.textContent="پشتیبان خودکار در دسترس نیست؛ نسخهٔ دانلودی را بررسی کنید.";}}
  function registerEnhancements(){document.addEventListener("click",enhancedClick,true);document.addEventListener("pointerdown",companyOptionPointerDown,true);if(!("PointerEvent"in window))document.addEventListener("touchstart",companyOptionPointerDown,{capture:true,passive:false});document.addEventListener("pointerdown",pointerStart,true);window.addEventListener("pointerup",stopHold,true);window.addEventListener("pointercancel",stopHold,true);document.addEventListener("touchend",stopHold,{capture:true,passive:true});document.addEventListener("touchcancel",stopHold,{capture:true,passive:true});document.addEventListener("lostpointercapture",stopHold,true);window.addEventListener("blur",stopHold);window.addEventListener("pagehide",stopHold);document.addEventListener("visibilitychange",function(){if(document.hidden)stopHold();else{refreshDateViews();checkNotifications();}});document.addEventListener("submit",captureSubmit,true);document.addEventListener("input",captureInput,true);document.addEventListener("focusout",focusoutFormatNumber,true);document.addEventListener("focusin",function(e){if(e.target&&e.target.id==="insurance-company")showInsuranceCompanyOptions(e.target.value);},true);document.addEventListener("focusout",function(e){if(e.target&&e.target.id==="insurance-company"){const wrap=q("#insurance-company-autocomplete");if(!wrap||!wrap.contains(e.relatedTarget))closeInsuranceCompanyOptions();}},true);document.addEventListener("keydown",enhancedCardKeydown,true);document.addEventListener("change",function(e){if(e.target===documentKindSelect){e.stopImmediatePropagation();toggleDocumentFields();}else if(e.target&&e.target.id==="service-km-reminder-enabled")updateKmReminderVisibility();else if(e.target&&e.target.id==="insurance-type")updateInsuranceOtherTypeField();},true);odometerConfirmDialog.addEventListener("cancel",function(event){event.preventDefault();rejectOdometerConfirmation();});const dueCountCard=q("#due-count-card");if(dueCountCard){dueCountCard.addEventListener("click",scrollToNearestDue);dueCountCard.addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();scrollToNearestDue();}});}if(notificationTimer===null)notificationTimer=setInterval(function(){refreshDateViews();checkNotifications();maybeCreateMonthlyBackup();},30000);updateNotificationStatus();checkNotifications();}
  const originalOpenVehicleDialog=window.openVehicleDialog;window.openVehicleDialog=function(){originalOpenVehicleDialog();formatFaNumberInputs(vehicleForm);};window.openServiceDialog=window.openServiceDialog;window.toggleDocumentFields=window.toggleDocumentFields;window.renderReminders=window.renderReminders;
  const originalSaveState=window.saveState;window.saveState=function(){const ok=originalSaveState.apply(this,arguments);if(ok)maybeCreateMonthlyBackup();return ok;};state=normState(state);state.version=DATA_VERSION;saveState();registerEnhancements();updateServiceCostPreview();render();restoreAutoBackupIfEmpty();
